#!/usr/bin/env python3
"""Publish only evidence/contract files after all real V3 checks have passed."""
import hashlib,json,platform,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4];B=Path(__file__).resolve().parent;OUT=B/'v3'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,d):(OUT/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
def main():
 files=['verification.json','metadata-verification.json','determinism-verification.json','complete-page-authority-verification.json','mixed-heading-import-verification.json','whole-body-material-assignment.json'];proofs={n:json.loads((OUT/n).read_text())for n in files};assert all(d['passed']for d in proofs.values());vp=proofs['verification.json'];assert vp['expected_count']==vp['actual_count']==1199
 supplementary=[B/'v2/identifier-syntax-closure.json',B/'v2/residual-column-census.json',B/'independent-ifa-continuation-census.json',B/'v2/mixed-coded-field-headings.json'];assert all(json.loads(p.read_text()).get('passed')for p in supplementary)
 sources=json.loads((OUT/'integration-proposal.json').read_text())['proposed_sources'];allsource={s['id']:s for s in json.loads((ROOT/'data/manifests/bncc-southeast.json').read_text())};oracle=json.loads((OUT/'corrective-oracle.json').read_text());views=[]
 for p in sorted((ROOT/'var/private-evidence/es-coded-body-review').glob('*.png')):views.append({'path':str(p.relative_to(ROOT)),'sha256':sha(p),'agent_inspected':True,'human_review':False})
 save('visual-review.json',{'actor_type':'automated','method':'Agent inspection of original PDF rasters, stratified by source, false fill subdivisions, p77 overlapping columns, all12historical continuation candidates, four literal new code spellings, and two same-field axis-heading boundaries. All-cell source/trace verification is separate.','raster_files':views,'raster_count':len(views),'sample_regions':26,'original_continuation_crops':12,'human_review':False,'source_limitations':['Original PDFs contain right-edge clipping/overhang; original embedded source glyphs are retained without dictionary repair.','Six native paint-stream order differences are explicitly recorded; canonical order follows physical positions and visible glyph trace.','Visual samples are agent review, not human or all-cell pixel verification.']})
 inputpaths=[ROOT/'data/manifests/uncoded/es-complement-coded-v3-extract.py',ROOT/'data/manifests/uncoded/es-complement-coded-extract.py']
 for n in ['audit_columns.py','verify_metadata.py','verify_v3_metadata.py','verify_v3_contract.py','verify_v3_assignment.py','verify_mixed_heading_import.py','mixed_field_headings.py','census_identifier_syntax.py','census_ifa_continuations.py','residual_column_census.py','finalize_contract.py','continuation-reassessment.json']:
  inputpaths.append(B/n)
 for name in ['coded-closure.json','expected-learning-inventory.json','prefix-learning-inventory.json']:inputpaths.append(B.parent/name)
 for p in sorted(B.glob('literal-physical-*.json')):
  if p.name!='literal-physical-summary.json':inputpaths.append(p)
 inputpaths+=[B/'v2/mixed-coded-field-headings.json']
 for s in sources:
  label=Path(s['uncoded_items_path']).stem.removeprefix('es-complement-coded-v3-');inputpaths.append(ROOT/f'data/manifests/uncoded/es-complement-coded-{label}.json')
 closure=json.loads((B.parent/'coded-closure.json').read_text())
 for s in closure['source_summaries']:
  if s['source_id']in{q['source_id']for q in sources}:inputpaths.append(ROOT/s['finalized_path'])
 current={p.name:sha(p)for p in(ROOT/'pipeline').glob('*.py')};parser_changes={k:{'verified':vp['pipeline_after'].get(k),'current':current.get(k)}for k in set(current)|set(vp['pipeline_after'])if current.get(k)!=vp['pipeline_after'].get(k)};loaded_changes={k:{'verified':d,'current':current.get(k)}for k,d in vp['loaded_parser_fingerprint']['files'].items()if current.get(k)!=d};assert not loaded_changes
 inputreport={'actor_type':'automated','inputs':[{'path':str(p.relative_to(ROOT)),'sha256':sha(p)}for p in inputpaths],'original_sources':[{**s,'local_path':allsource[s['source_id']]['local_path'],'pdf_sha256_matches':sha(ROOT/allsource[s['source_id']]['local_path'])==s['source_sha256']}for s in sources],'runtime':{'python':platform.python_version(),'executable':sys.executable},'loaded_parser_fingerprint':vp['loaded_parser_fingerprint'],'loaded_parser_changes_since_real_importer_proof':loaded_changes,'all_pipeline_file_changes_since_real_importer_proof':parser_changes,'prior_checkpoint_change_note':'raster_review_scoped.py was added concurrently after V2. V3 real proof began after that addition; no loaded parser code was changed by this agent.','source_pdfs_readonly':True,'extraction_caches_readonly':True,'full_parser_rerun':False,'manifest_modified':False,'core_modified':False,'human_review':False};save('inputs-contract.json',inputreport)
 for s in sources:
  ids=sorted(r['expected_id']for r in oracle['records']if r['source_id']==s['source_id']);s['expected_id_count']=len(ids);s['expected_ids_sha256']=hashlib.sha256(('\n'.join(ids)+'\n').encode()).hexdigest();s['expected_ids_source']={'path':str((OUT/'corrective-oracle.json').relative_to(ROOT)),'sha256':sha(OUT/'corrective-oracle.json'),'json_filter':'records where source_id matches; expected_id'};assert sha(ROOT/s['uncoded_items_path'])==s['sidecar_sha256']
 contract={'actor_type':'automated','status':'implemented_executed_and_verified__owner_composition_pending','version':'v3','sources':sources,'total_records':1199,'learning_definitions':1181,'contextual_reference_records':18,'physical_reference_mentions':21,'preserved_existing_ids':1160,'new_literal_ids':39,'corrected_existing_bodies':335,'headings_excluded_from_learning_bodies':21,'real_continuations':11,'proposed_mixed_heading_nodes':46,'proposed_coded_parent_links':120,'proofs':[{'path':str((OUT/n).relative_to(ROOT)),'sha256':sha(OUT/n),'passed':True}for n in files]+[{'path':str(p.relative_to(ROOT)),'sha256':sha(p),'passed':True}for p in supplementary],'hierarchy_proposal':{'path':str((B/'v2/mixed-coded-field-headings.json').relative_to(ROOT)),'sha256':sha(B/'v2/mixed-coded-field-headings.json'),'nodes':46,'links':120,'actual_importer_proof':str((OUT/'mixed-heading-import-verification.json').relative_to(ROOT)),'owner_must_merge_deduplicate_and_bind_course_unit':True},'inputs_contract_sha256':sha(OUT/'inputs-contract.json'),'visual_review_sha256':sha(OUT/'visual-review.json'),'integration_required':'Merge each complete coded wrapper with the owner source-specific uncoded/hierarchy wrapper; preserve literal codes and technical locators/IDs; apply proposed coded_learning_ranges only after all records and honest references on those pages are present. There is one uncoded_items_path per source.','pending':['Owner composition/deduplication with uncoded objectives and hierarchy, then manifest pin integration.','Other11 ES baseline sources have not received this new full-body audit in this subfront.','Human review remains pending; no readyUF or curricular equivalence asserted.'],'obsolete_checkpoints':['V1: missing39 literal printed identifiers.','V2:21 following axis headings remained attached to learning bodies.'],'source_pdfs_readonly':True,'extraction_caches_readonly':True,'manifest_modified':False,'core_modified':False,'human_review':False};save('final-contract.json',contract);print('FINAL',sha(OUT/'final-contract.json'));print('ORACLE',sha(OUT/'corrective-oracle.json'));print('PIPELINE_CHANGES',parser_changes)
if __name__=='__main__':main()
